// Builds the Shopify customer (merged tags + note) from the form answers.
const s = $('Settings').first().json;
const f = $('Wholesale application form').first().json;
const found = $input.first().json;
const existing = found?.data?.customers?.nodes?.[0] || null;
const lookupError = found?.error ? (found.error.message || 'Shopify lookup failed') : (found?.errors ? JSON.stringify(found.errors) : '');

const email = String(f['Email'] || '').trim().toLowerCase();
const fullName = String(f['Your name'] || '').trim();
const firstName = fullName.split(/\s+/)[0] || '';
const lastName = fullName.split(/\s+/).slice(1).join(' ');

const answers = [
  ['Company', f['Company name']],
  ['Contact', fullName],
  ['Email', email],
  ['Phone', f['Phone']],
  ['Website', f['Website']],
  ['Business type', f['Business type']],
  ['Tax ID / resale cert', f['Tax ID / resale certificate number']],
  ['Monthly order value', f['Estimated monthly order value']],
  ['Message', f['Anything else we should know?']],
].filter(([, v]) => v !== undefined && v !== null && String(v).trim() !== '');

const today = new Date().toISOString().slice(0, 10);
const block = `Wholesale application ${today}\n` + answers.map(([k, v]) => `${k}: ${v}`).join('\n');
const oldTags = existing ? existing.tags : [];
const alreadyWholesale = oldTags.map(t => t.toLowerCase()).includes(String(s.approvedTag).toLowerCase());
const tags = [...new Set([...oldTags, s.pendingTag])];
const note = existing && existing.note ? `${existing.note}\n\n${block}` : block;

const input = { email, tags, note };
if (!existing) { input.firstName = firstName; if (lastName) input.lastName = lastName; }

return [{ json: {
  email, fullName, firstName, company: String(f['Company name'] || '').trim(), answers,
  isExisting: !!existing, alreadyWholesale, lookupError,
  // If the lookup failed we don't know the existing tags, so don't write (would overwrite them).
  setBody: lookupError ? { query: '{ shop { id } }' } : { query: "mutation($id: CustomerSetIdentifiers, $input: CustomerSetInput!) { customerSet(identifier: $id, input: $input) { customer { id } userErrors { field message } } }", variables: { id: { email }, input } },
} }];

// Builds the owner email. Works even if saving to Shopify failed.
const s = $('Settings').first().json;
const a = $('Build Shopify customer').first().json;
const res = $input.first().json;
const c = res?.data?.customerSet?.customer;
const userErrors = res?.data?.customerSet?.userErrors || [];
let problem = a.lookupError || '';
if (!c) problem = problem || (res?.error?.message) || (userErrors.map(e => e.message).join('; ')) || (res?.errors ? JSON.stringify(res.errors) : 'Unknown Shopify error');
const esc = v => String(v).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const custUrl = c ? `https://admin.shopify.com/store/${s.shopSubdomain}/customers/${c.id.split('/').pop()}` : '';
const rows = a.answers.map(([k, v]) => `<tr><td style="padding:4px 12px 4px 0;color:#666;vertical-align:top">${esc(k)}</td><td style="padding:4px 0">${esc(v).replace(/\n/g, '<br>')}</td></tr>`).join('');
const status = !c
  ? `<p style="background:#fdecea;padding:10px;border-radius:6px"><b>Not saved to Shopify:</b> ${esc(problem)}<br>Check the Shopify credential and its scopes (read_customers, write_customers), then add this customer by hand.</p>`
  : a.alreadyWholesale
    ? `<p style="background:#fff4e5;padding:10px;border-radius:6px">This customer already has the <b>${esc(s.approvedTag)}</b> tag.</p>`
    : `<p>${a.isExisting ? 'Existing customer' : 'New customer'} saved in Shopify and tagged <b>${esc(s.pendingTag)}</b>.</p>`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:600px">
<h2 style="margin:0 0 8px">New wholesale application</h2>
${status}
<table style="border-collapse:collapse;margin:12px 0">${rows}</table>
${c ? `<p><a href="${custUrl}" style="background:#008060;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none">Open customer in Shopify</a></p>` : ''}
<p style="color:#666"><b>To approve:</b> in Shopify add a company for this customer (Customers → Companies) and give it your wholesale catalog and payment terms, or replace the tag <b>${esc(s.pendingTag)}</b> with <b>${esc(s.approvedTag)}</b> if you use tag-based wholesale.</p>
</div>`;
return [{ json: {
  subject: `${c ? '' : '[Not saved] '}Wholesale application: ${a.company} (${a.fullName})`,
  html, email: a.email, firstName: a.firstName, company: a.company,
} }];
